// The public profile's tokenless validators for public Bitspark constellation members (#1096 item 3).
//
// Generated by `atlas gate export` from Bitspark/atlas@f90ccbaa235367d7f5d513bee3ab8d9507cb4e14. Do not edit by hand: change
// atlas, then re-export. The function bodies below are atlas's own — the readers `atlas public profile`
// runs — so this checker reaches the same verdicts on the same inputs.
//
// It reads only the repository under test (atlas.json, .atlas/process.json, the docs pages, the
// atlas-managed regions of .gitattributes and .gitignore, and the member-owned files it reports on)
// plus policy.json. It never runs the repository's code, never reaches the network, needs no token,
// and writes nothing.

import { readFileSync, existsSync, statSync, realpathSync, readdirSync } from "node:fs";
import { join, relative, resolve, dirname, sep, posix } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import process from "node:process";

// ── from atlas src/docs.mjs ──

function headingText(raw) {
  return raw
    .replace(/<!--[\s\S]*?-->/g, "")
    .replace(/<[^>]+>/g, "")
    .replace(/!\[([^\]]*)\]\([^)]*\)/g, "$1") // image -> alt
    .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1") // link  -> text
    .replace(/\[([^\]]*)\]\[[^\]]*\]/g, "$1") // ref link -> text
    .replace(/`([^`]*)`/g, "$1") // inline code
    .replace(/[*~]/g, "") // emphasis / strikethrough markers
    .replace(/(?<![\p{L}\p{N}_])_+|_+(?![\p{L}\p{N}_])/gu, "")
    .trim();
}

function slug(raw) {
  return headingText(raw)
    .toLowerCase()
    .replace(/[^\p{L}\p{M}\p{N}_\- ]+/gu, "")
    .replace(/ /g, "-");
}

function slugAll(headingTexts) {
  const seen = new Map();
  const out = [];
  for (const h of headingTexts) {
    const base = slug(h);
    const n = seen.get(base) ?? 0;
    seen.set(base, n + 1);
    out.push(n === 0 ? base : `${base}-${n}`);
  }
  return out;
}

function maskCode(md) {
  const lines = md.split("\n");
  let fence = null; // the open fence marker, or null
  return lines
    .map((line) => {
      const m = /^\s*(```+|~~~+)/.exec(line);
      if (fence) {
        if (m && line.trim().startsWith(fence)) { fence = null; return ""; }
        return "";
      }
      if (m) { fence = m[1].slice(0, 3) === "~~~" ? "~~~" : "```"; return ""; }
      return line;
    })
    .join("\n");
}

function headings(md) {
  const masked = maskCode(md);
  const lines = masked.split("\n");
  const raw = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const atx = /^ {0,3}(#{1,6})\s+(.*?)\s*#*\s*$/.exec(line);
    if (atx) { raw.push({ depth: atx[1].length, text: atx[2].trim() }); continue; }
    const next = lines[i + 1];
    if (next && line.trim() && !/^ {0,3}#/.test(line)) {
      if (/^ {0,3}=+\s*$/.test(next)) { raw.push({ depth: 1, text: line.trim() }); i++; continue; }
      if (/^ {0,3}-+\s*$/.test(next)) { raw.push({ depth: 2, text: line.trim() }); i++; continue; }
    }
  }
  const anchors = slugAll(raw.map((h) => h.text));
  return raw.map((h, i) => ({ depth: h.depth, text: headingText(h.text), anchor: anchors[i] }));
}

function explicitAnchors(md) {
  const masked = maskCode(md);
  const out = new Set();
  const re = /<a\b[^>]*?\b(?:id|name)\s*=\s*"([^"]+)"/gi;
  let m;
  while ((m = re.exec(masked))) out.add(decodeURIComponent(m[1]));
  return out;
}

function anchorsOf(md) {
  const set = new Set(headings(md).map((h) => h.anchor));
  for (const a of explicitAnchors(md)) set.add(a);
  return set;
}

function links(md) {
  const masked = maskCode(md);
  const out = [];
  const inline = /\[(?:[^\]]*)\]\(\s*(<[^>]*>|[^()\s]+(?:\([^()]*\)[^()\s]*)*)\s*(?:"[^"]*"|'[^']*')?\s*\)/g;
  let m;
  while ((m = inline.exec(masked))) {
    let t = m[1].trim();
    if (t.startsWith("<") && t.endsWith(">")) t = t.slice(1, -1);
    out.push({ target: t, raw: m[0] });
  }
  const refdef = /^ {0,3}\[[^\]]+\]:\s*(\S+)/gm;
  while ((m = refdef.exec(masked))) {
    out.push({ target: m[1].trim(), raw: m[0] });
  }
  const href = /(?:href|src|srcset)\s*=\s*"([^"]+)"/gi;
  while ((m = href.exec(md))) {
    for (const part of m[1].split(",")) {
      const url = part.trim().split(/\s+/)[0];
      if (url) out.push({ target: url, raw: m[0] });
    }
  }
  return out;
}

const toPosix = (p) => p.split(sep).join("/");

function discoverPages(root, { docsDir = "docs", includeRootReadme = true, extraDirs = [] } = {}) {
  const pages = new Set();
  if (includeRootReadme && existsSync(join(root, "README.md"))) pages.add("README.md");
  for (const d of [docsDir, ...extraDirs]) {
    const abs = join(root, d);
    if (existsSync(abs) && statSync(abs).isDirectory()) {
      walk(abs, (file, name) => {
        if (name.toLowerCase().endsWith(".md")) pages.add(toPosix(relative(root, file)));
      });
    }
  }
  return [...pages].sort();
}

function readPage(root, rel) {
  let md;
  try { md = readFileSync(join(root, rel), "utf8"); } catch { return null; }
  return { rel, anchors: anchorsOf(md), links: links(md) };
}

function buildGraph(root, opts = {}) {
  const order = discoverPages(root, opts);
  const pages = new Map();
  for (const rel of order) {
    const p = readPage(root, rel);
    if (p) pages.set(rel, p);
  }
  return { pages, order };
}

// ── from atlas src/workspace.mjs ──

const SKIP_DIRS = new Set([
  "node_modules", ".git", ".claude", ".worktrees", ".atlas-cli",
  "target", "dist", "build", ".next", "vendor", "coverage",
]);

function walk(root, onFile) {
  const seen = new Set();
  const visit = (dir) => {
    let real;
    try { real = realpathSync(dir); } catch { return; }
    if (seen.has(real)) return; // symlink-cycle guard
    seen.add(real);
    let entries;
    try { entries = readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const e of entries) {
      if (e.isDirectory()) {
        if (!SKIP_DIRS.has(e.name)) visit(join(dir, e.name));
      } else {
        onFile(join(dir, e.name), e.name);
      }
    }
  };
  visit(root);
}

// ── from atlas src/commands/docs.mjs ──

const DEFAULTS = {
  docsDir: "docs",
  indexThreshold: 3,
  dirIndexThreshold: 3,
  decisionsDir: "decisions",
  extraDirs: [],
};

const DOCS_MANIFEST = (docsDir) => `${docsDir}/.docs-manifest.json`;

function readDocsBlock(root) {
  const p = join(root, "atlas.json");
  if (!existsSync(p)) return {};
  try {
    const m = JSON.parse(readFileSync(p, "utf8"));
    return m.docs && typeof m.docs === "object" ? m.docs : {};
  } catch { return {}; }
}

function assembleDocsManifest(root, opts = {}) {
  const o = { ...DEFAULTS, ...opts };
  const graph = buildGraph(root, { docsDir: o.docsDir });
  const block = readDocsBlock(root);
  const findings = [];

  const pages = {};
  for (const rel of graph.order) {
    const page = graph.pages.get(rel);
    pages[rel] = [...page.anchors];
  }

  const exportsOut = [];
  for (const ex of Array.isArray(block.exports) ? block.exports : []) {
    const label = ex.id ?? ex.path ?? "(unnamed export)";
    const rel = ex.path ? toPosix(ex.path) : null;
    const known = rel && pages[rel] ? new Set(pages[rel]) : null;
    const anchors = Array.isArray(ex.anchors) ? ex.anchors : [];
    if (!known) {
      findings.push({
        rule: "docs-export-path",
        severity: "error",
        message: ex.path
          ? `export \`${label}\`: path \`${ex.path}\` does not resolve to a discovered docs page`
          : `export \`${label}\`: no \`path\` — cannot resolve to a docs page`,
      });
    } else {
      const unknown = anchors.filter((a) => !known.has(a));
      if (unknown.length) {
        findings.push({
          rule: "docs-export-anchor",
          severity: "error",
          message: `export \`${label}\` (${rel}): unknown heading anchor(s) ${unknown.map((a) => `#${a}`).join(", ")}`,
        });
      }
    }
    exportsOut.push({
      id: ex.id,
      kind: ex.kind ?? "doc",
      path: rel,
      anchors,
      ...(known ? { unknownAnchors: anchors.filter((a) => !known.has(a)) } : {}),
    });
  }

  const doc = {
    _comment:
      "GENERATED by `atlas docs export` from this repo's atlas.json `docs` block + the discovered headings — do not edit by hand. Run `atlas docs export` to regenerate; `--check` fails CI on drift.",
    ...(block.entry ? { entry: toPosix(block.entry) } : {}),
    pages,
    exports: exportsOut,
  };
  return { doc, findings };
}

// ── from atlas src/commands/workflow.mjs ──

const norm = (s) => s.replace(/\r\n/g, "\n");

const MANAGED_BEGIN = "# >>> atlas-managed — `atlas workflow sync` owns this block; do not edit inside >>>";

const MANAGED_END = "# <<< atlas-managed <<<";

function extractManagedBlock(text) {
  const lines = norm(text).split("\n");
  const b = lines.indexOf(MANAGED_BEGIN);
  const e = lines.indexOf(MANAGED_END);
  if (b === -1 || e === -1 || e < b) return null;
  return lines.slice(b + 1, e).join("\n").replace(/\n+$/, "");
}

// ── from atlas src/commands/public-profile.mjs ──

const SECURITY_CHANNEL = /private vulnerability reporting|security advisor|report (it |a vulnerability )?privately|security@[a-z0-9.-]+|report a vulnerability/i;

function applySanctioned(findings, sanctioned) {
  if (sanctioned == null || typeof sanctioned !== "object" || Array.isArray(sanctioned)) return findings;
  const out = [];
  const malformed = new Set();
  const entryFor = (f) => {
    for (const k of f.subject != null ? [`${f.rule}:${f.subject}`, f.rule] : [f.rule]) {
      if (Object.prototype.hasOwnProperty.call(sanctioned, k)) return { key: k, entry: sanctioned[k] };
    }
    return null;
  };
  for (const f of findings) {
    const hit = f.severity === "warning" ? entryFor(f) : null;
    if (!hit) { out.push(f); continue; }
    const e = hit.entry;
    if (!e || typeof e !== "object" || Array.isArray(e) || typeof e.reason !== "string" || !e.reason.trim()) { malformed.add(hit.key); out.push(f); continue; }
    const by = typeof e.by === "string" && e.by ? ` by ${e.by}` : "";
    const since = typeof e.since === "string" && e.since ? ` on ${e.since}` : "";
    out.push({ ...f, severity: "info", sanctioned: hit.key, message: `${f.message} — sanctioned${by}${since}: ${e.reason.trim()}` });
  }
  for (const k of malformed) {
    out.push({ rule: "public-profile:sanctioned", severity: "warning", message: `.atlas/process.json sanctioned["${k}"] is malformed (expected { reason, by?, since? }); it waives nothing` });
  }
  return out;
}

// ── entry point ───────────────────────────────────────────────────────────────────────────────────

const HERE = dirname(fileURLToPath(import.meta.url));
const PIN_REL = ".atlas/process.json";

/** The public profile's validators over `repoPath`, with the facts in `policyPath`'s `profile` block.
 *  Prints one line per finding and a verdict; returns an exit code. An ERROR fails the job: the
 *  governance pin missing or at another specVersion, the docs manifest missing or stale where
 *  atlas.json declares `docs`, an atlas-managed region missing or changed, or a policy with no
 *  profile. The member-owned content (security policy, issue chooser, PR template, agent docs) is
 *  REPORTED against its contract as a warning and never fails; the pin's `sanctioned` map (a member's
 *  recorded decision) turns a warning into an info carrying the reason, exactly as `atlas public
 *  profile` does, under the same rule names, so one waiver covers both. */
export function runProfile(repoPath = ".", policyPath = join(HERE, "policy.json")) {
  const root = resolve(repoPath);
  let profile;
  try {
    profile = JSON.parse(readFileSync(policyPath, "utf8")).profile;
  } catch (e) {
    process.stderr.write(`  ✗ [error] profile/policy: cannot read the policy (${e.message}); nothing was checked\n`);
    return 1;
  }
  if (!profile || !Number.isInteger(profile.specVersion) || !Array.isArray(profile.managedBlocks) || profile.managedBlocks.length === 0 || !Array.isArray(profile.owned)) {
    process.stderr.write("  ✗ [error] profile/policy: the policy carries no profile (specVersion, managedBlocks, owned); nothing was checked\n");
    return 1;
  }
  const findings = [];
  const readJsonAt = (rel) => {
    try { return JSON.parse(readFileSync(join(root, rel), "utf8")); } catch { return null; }
  };

  // (1) The governance pin: present and at the contract's specVersion.
  const pin = readJsonAt(PIN_REL);
  if (!pin) {
    findings.push({ rule: "public-profile:pin", severity: "error", message: `${PIN_REL} is missing or unreadable; the public profile pins it at specVersion ${profile.specVersion} (atlas public converge proposes it)` });
  } else if (pin.specVersion !== profile.specVersion) {
    findings.push({ rule: "public-profile:pin", severity: "error", message: `${PIN_REL} is pinned at specVersion ${pin.specVersion}; the contract is at ${profile.specVersion} (atlas public converge re-pins it)` });
  } else {
    findings.push({ rule: "public-profile:pin", severity: "info", message: `${PIN_REL} is pinned at specVersion ${profile.specVersion}` });
  }

  // (2) The docs manifest, only where atlas.json declares `docs`: regenerated here, byte-compared
  // (CRLF-normalized) with the committed one.
  const manifest = readJsonAt("atlas.json");
  const docsDir = profile.docsDir ?? DEFAULTS.docsDir;
  if (!manifest) {
    findings.push({ rule: "public-profile:manifest", severity: "error", message: "atlas.json is missing or unreadable" });
  } else if (manifest.docs && typeof manifest.docs === "object") {
    const rel = DOCS_MANIFEST(docsDir);
    if (!existsSync(join(root, docsDir))) {
      findings.push({ rule: "public-profile:docs", severity: "warning", message: `atlas.json declares \`docs\` but there is no ${docsDir}/ directory to hold the manifest` });
    } else {
      const assembled = assembleDocsManifest(root, { docsDir });
      const errors = assembled.findings.filter((f) => f.severity === "error");
      if (errors.length) {
        for (const f of errors) findings.push({ rule: `public-profile:docs:${f.rule}`, severity: "error", message: f.message });
      } else {
        const next = JSON.stringify(assembled.doc, null, 2) + "\n";
        let current = null;
        try { current = readFileSync(join(root, rel), "utf8").replaceAll("\r\n", "\n"); } catch { /* absent */ }
        if (current === next) findings.push({ rule: "public-profile:docs", severity: "info", message: `${rel} is current` });
        else findings.push({ rule: "public-profile:docs", severity: "error", message: `${rel} is ${current == null ? "missing" : "stale"}; atlas public converge regenerates it` });
      }
    }
  } else {
    findings.push({ rule: "public-profile:docs", severity: "info", message: "atlas.json declares no `docs`, so there is no docs manifest to check" });
  }

  // (3) The atlas-managed regions: present and equal to the canonical body; the rest of each file is
  // the member's and is not read.
  for (const block of profile.managedBlocks) {
    let current = null;
    try { current = readFileSync(join(root, block.path), "utf8"); } catch { /* absent */ }
    const want = norm(block.body).replace(/\n+$/, "");
    const have = current == null ? null : extractManagedBlock(current);
    if (have === want) {
      findings.push({ rule: `public-profile:${block.id}`, severity: "info", message: `${block.path} carries the atlas-managed region` });
    } else {
      const why = current == null ? "is missing" : have == null ? "has no atlas-managed region" : "has a changed atlas-managed region";
      findings.push({ rule: `public-profile:${block.id}`, severity: "error", message: `${block.path} ${why}; atlas public converge merges it (only the region between the atlas-managed markers is atlas's)` });
    }
  }

  // (4) The member-owned content: reported against its contract, never failed, never written.
  for (const item of profile.owned) {
    if (!existsSync(join(root, item.path))) {
      findings.push({ rule: `public-profile:${item.id}`, severity: "warning", subject: item.path, message: `${item.path} is missing; the contract: ${item.contract} (the member writes its own; atlas never seeds it here)` });
      continue;
    }
    if (item.id === "security-policy" && !SECURITY_CHANNEL.test(readFileSync(join(root, item.path), "utf8"))) {
      findings.push({ rule: `public-profile:${item.id}`, severity: "warning", subject: item.path, message: `${item.path} names no private reporting channel (GitHub private vulnerability reporting or a security address); the contract: ${item.contract}` });
      continue;
    }
    findings.push({ rule: `public-profile:${item.id}`, severity: "info", message: `${item.path} is the member's own and meets the contract` });
  }

  const reported = applySanctioned(findings, pin && typeof pin === "object" ? pin.sanctioned ?? null : null);
  const errors = reported.filter((f) => f.severity === "error").length;
  const warnings = reported.filter((f) => f.severity === "warning").length;
  for (const f of reported) {
    const mark = f.severity === "error" ? "✗" : f.severity === "warning" ? "!" : "·";
    process.stdout.write(`  ${mark} [${f.severity}] ${f.rule}: ${f.message}\n`);
  }
  process.stdout.write(`public profile: ${errors ? "does not hold" : "holds"} — ${errors} error(s), ${warnings} warning(s), ${reported.length - errors - warnings} note(s)\n`);
  return errors ? 1 : 0;
}

// For this distribution's own tests: the region markers and the readers the checks use (a function, so the
// entry file parses on its own: the names resolve only in the assembled distribution).
export const shipped = () => ({ MANAGED_BEGIN, MANAGED_END, extractManagedBlock, assembleDocsManifest, DOCS_MANIFEST });

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  // profile.mjs [path]
  process.exit(runProfile(process.argv[2] ?? "."));
}
